{"action": "write", "path": "duration.py", "content": "import re


_DURATION_RE = re.compile(
    r"^(?:(?P<d>[0-9]+)d)?"
    r"(?:(?P<h>[0-9]+)h)?"
    r"(?:(?P<m>[0-9]+)m)?"
    r"(?:(?P<s>[0-9]+)s)?$"
)

_MULTIPLIERS = {
    "d": 24 * 60 * 60,
    "h": 60 * 60,
    "m": 60,
    "s": 1,
}


def parse_duration(s):
    """Convert a duration string such as '1h30m' to an integer number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("empty duration")

    match = _DURATION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for unit, multiplier in _MULTIPLIERS.items():
        amount = match.group(unit)
        if amount is not None:
            total += int(amount) * multiplier

    return total
